def merge_oom_and_reconnect_events(
    oom_events: list[dict[str, str]], reconnects: list[dict[str, str]]
) -> list[dict[str, str]]:
    events = list(oom_events)
    for reconnect in reconnects:
        reconnect_time = parse_utc(reconnect["timestamp"])
        explained_by_oom = any(
            oom_time <= reconnect_time
            and (reconnect_time - oom_time).total_seconds()
            <= OOM_RECONNECT_CORRELATION_SECONDS
            for oom_time in (parse_utc(event["timestamp"]) for event in oom_events)
        )
        if not explained_by_oom:
            events.append(reconnect)
    return events


